import logging
from time import sleep
from traceback import format_exception

from taf.ul.marvin.marvin_ute_client import MarvinUteClient
from taf.ul.marvin.utilities import Utilities


class marvin:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.marvin_ute_client = None
        self.utils = Utilities()
        self.run_marvin = True
        self.test_env = {}
        self._test_run_created = False
        self._test_run_started = False
        self._test_case_created = False
        self._test_case_started = False

    def download_and_install_marvin(self, proxy=False, script_update=True, install_marvin_from_rsp_pypi=False):
        """
        Downloads and installs Marvin. This method updates the data collectors and imports the Marvin client.

        :param bool proxy: If True, uses a proxy for Marvin scripts download and installation. Proxy needs to be set
                           in the environment variables.
        :param bool script_update: If True, updates the Marvin scripts before installation. Default is True.
        :param bool install_marvin_from_rsp_pypi: If True, installs Marvin from RSP PyPI repository. As default (False),
                                                  marvin-cli is mirrored to ute-pypi and doesn't need to be installed
                                                  separately.
        """
        self.marvin_ute_client.update_collectors(proxy, script_update, install_marvin_from_rsp_pypi)
        if install_marvin_from_rsp_pypi:
            self.marvin_ute_client.import_marvin_client()

    def prepare_and_start_marvin(self, test_case_name="Default", ref_run_id="", ref_case_id="", only_test_run=False,
                                 adapter_list=None, marvin_folder="/home/ute/marvin",
                                 common_templates="",
                                 organization="Default", marvin_side="prod", print_marvin_link=False,
                                 create_test_cases=False, test_case_templates=None, proxy=False,
                                 script_update=True, install_marvin_from_rsp_pypi=False, cluster=None,
                                 test_run_type="CRT", test_line_type="", bts_role=None):
        """
        Prepares and starts Marvin server. This method initializes the Marvin environment, creates a test run, and
        starts the test case. It also handles the import of the Marvin client and updates the data collectors.
        The method takes care of the setup and teardown of the Marvin environment, including fetching snapshots and
        stopping the test run.

        :param str test_case_name: Name of the test case to be created and started.
        :param str ref_run_id: (Optional) Reference run ID for the test run. This is found from Marvin UI
        :param str ref_case_id: (Optional) Reference case ID for the test case. This is found from Marvin UI
        :param bool only_test_run: If True, only the test run is created and started, without starting the test case.
        :param list adapter_list: (Optional) Adapters for the test case. E.g. ["-cpu-mem"] disabeles cpu and memory
                                  checks.
        :param str marvin_folder: Folder where Marvin is installed. Default is "/home/ute/marvin".
        :param str common_templates: Templates for Marvin. If not set, it uses the default common templates from the
                                     library
        :param str organization: Organization name for Marvin.
        :param str marvin_side: (Optional)Side of the Marvin server (prod or dev). Default is "prod".
        :param bool print_marvin_link: (Optional)If True, prints the link to the Marvin run.
        :param bool create_test_cases: (Optional)If True, all test cases are created beforehand. stop_test_case will
                                        need test case name as an argument
        :param list test_case_templates: (Optional) Folder path(s) to the test case templates.
        :param bool proxy: (Optional) If True, uses a proxy for Marvin scripts download and installation. Proxy needs
                           to be set in the environment variables. Default is False.
        :param bool script_update: (Optional) If True, updates the Marvin scripts before installation. Default is True.
        :param bool install_marvin_from_rsp_pypi: (Optional) If True, installs Marvin from RSP PyPI repository.
                                                  As default (False), marvin-cli is mirrored to ute-pypi and doesn't
                                                  need to be installed separately.
        :param tuple cluster: (Optional) Predefined name and uuid of the cluster where the test is running. E.g.
                              ("ClusterA", "12345"). You can create uuid by "cat /proc/sys/kernel/random/uuid" or using
                              Python's uuid library.
        :param str test_run_type: (Optional) Type of the test run. Shown in Marvin Test run filters as 'Test type'.
                                   Default is "CRT".
        :param str test_line_type: (Optional) Type of the test line. Shown in Marvin BTS filters as 'Test type'.
                                   Default is empty string since UTE does not use it. Possible values: "1HB", "24HB",
                                   "BBU BM", "BM", "CRT, "New Feature", "Stability", "T-Gate ONE"
        :param str bts_role: (Optional) BTS role. "Master" | "Anchor" | "Secondary" | "Neighbor"
        """
        bts_id = self.utils.collect_bts_information("mrbtsID", mrbts_info=True)
        self.marvin_ute_client = MarvinUteClient(marvin_side, marvin_folder, common_templates, organization,
                                                 print_marvin_link, create_test_cases, bts_id)
        logging.debug("Prepare and start Marvin")
        if not bts_id:
            logging.error("BTS id is not get via admin. Can't start Marvin")
            self.run_marvin = False
            return
        if not self._setup_marvin_download(proxy, script_update, install_marvin_from_rsp_pypi):
            return
        if not self._prepare_test_run_steps(cluster, test_run_type, test_line_type, bts_role, ref_run_id):
            return
        if not only_test_run and not self._prepare_test_case_steps(
                test_case_name, test_case_templates, ref_case_id, adapter_list):
            return

    def _setup_marvin_download(self, proxy, script_update, install_marvin_from_rsp_pypi):
        """Run download_and_install_marvin; return True on success, False on exception (sets run_marvin=False)."""
        try:
            self.download_and_install_marvin(proxy, script_update, install_marvin_from_rsp_pypi)
            return True
        except Exception:
            logging.error("Error during Marvin setup. Check details in logs. Marvin will not be started")
            self.run_marvin = False
            return False

    def _run_marvin_step(self, step_name, step_callable):
        """Run a single step; return True on success, False on exception (sets run_marvin=False)."""
        try:
            step_callable()
            return True
        except Exception as e:
            logging.error(f"Error in {step_name}: {e}\n"
                          f"{''.join(format_exception(type(e), e, e.__traceback__))}")
            self.run_marvin = False
            return False

    def _prepare_test_run_steps(self, cluster, test_run_type, test_line_type, bts_role, ref_run_id):
        """Reset step state, create_test_run, start_test_run. Returns True if all succeeded."""
        self._test_run_created = False
        self._test_run_started = False
        self._test_case_created = False
        self._test_case_started = False
        if not self._run_marvin_step(
                "create_test_run",
                lambda: self.create_test_run(
                    cluster, test_run_type=test_run_type, test_line_type=test_line_type, bts_role=bts_role)):
            return False
        return self._run_marvin_step("start_test_run", lambda: self.start_test_run(ref=ref_run_id))

    def _prepare_test_case_steps(self, test_case_name, test_case_templates, ref_case_id, adapter_list):
        """create_test_case then start_test_case. Returns True if both succeeded."""
        if not self._run_marvin_step(
                "create_test_case",
                lambda: self.create_test_case(test_case_name, test_case_templates)):
            return False
        return self._run_marvin_step(
            "start_test_case",
            lambda: self.start_test_case(test_case_name, ref=ref_case_id, adapter_list=adapter_list))

    def stop_marvin(self, fetch_snapshot=False, only_test_run=False, verdict="Passed", wait_after_run=True,
                    link_to_rp=False, hide_std_messages=False):
        """
        Stops Marvin and fetches the snapshot if needed. It also stops the test case and test run, and waits for
        a specified time after the run to allow Marvin to finish its analysis.

        :param bool fetch_snapshot: If True, fetches the snapshot from Marvin before stopping it.
        :param bool only_test_run: If True, only stops the test run without stopping the test case.
        :param str/bool verdict: Verdict for the test run. Default is "Passed". It can also be a boolean value.
        :param wait_after_run: if True, returns final verdict and also waits for it before stopping Marvin.
        :param link_to_rp: If True, url to LAST marvin case is shown in RP.
                           Note! This is only usable when test is run via CM. Use either this or in stop_test_case,
                           not both.
        :param hide_std_messages: If True, hides standard messages from stopping docker during stopping Marvin.
        :returns bool: Final verdict of the test run
        """
        if not self.run_marvin:
            return ""
        return self._do_stop_marvin(
            fetch_snapshot, only_test_run, verdict, wait_after_run, link_to_rp, hide_std_messages)

    def _stop_marvin_case_and_run(self, verdict, only_test_run):
        """Stop test case (if started) and test run (if started)."""
        if not only_test_run and self._test_case_started:
            self.stop_test_case(verdict)
        if self._test_run_started:
            self.stop_test_run(verdict)

    def _do_stop_marvin(self, fetch_snapshot, only_test_run, verdict, wait_after_run, link_to_rp, hide_std_messages):
        """Perform stop_marvin logic when run_marvin is True. Returns final verdict or ''."""
        output = True
        logging.debug("Stop Marvin")
        if fetch_snapshot:
            self.marvin_ute_client.fetch_single_snapshot()
        self._stop_marvin_case_and_run(verdict, only_test_run)
        if wait_after_run:
            output = self.return_final_verdict()
        else:
            sleep(60)
        self.marvin_ute_client.stop_docker(no_std_messages=hide_std_messages)
        if link_to_rp:
            self.marvin_ute_client.add_marvin_link_to_rp()
        return output

    def create_test_run(self, cluster=None, test_run_type="CRT", test_line_type="", bts_role=None):
        """
        Creates a test run in Marvin

        :param tuple cluster: (Optional) Predefined name and uuid of the cluster where the test is running. E.g.
                              ("ClusterA", "12345"). You can create uuid by "cat /proc/sys/kernel/random/uuid" or
                              using Python's uuid library.
        :param str test_run_type: (Optional) Type of the test run. Shown in Marvin Test run filters as 'Test type'.
                                   Default is "CRT".
        :param str test_line_type: (Optional) Type of the test line. Shown in Marvin BTS filters as 'Test type'.
                                   Default is empty string since UTE does not use it. Possible values: "1HB", "24HB",
                                   "BBU BM", "BM", "CRT, "New Feature", "Stability", "T-Gate ONE"
        :param str bts_role: (Optional) BTS role. "Master" | "Anchor" | "Secondary" | "Neighbor"

        """
        if self.run_marvin:
            self.marvin_ute_client.create_test_run(cluster, test_run_type=test_run_type, test_line_type=test_line_type,
                                                   test_env=self.test_env, bts_role=bts_role)
            self._test_run_created = True

    def start_test_run(self, ref=""):
        """
        Starts the test run in Marvin.

        :param str ref: (Optional) Reference run ID for the test run. This is found from Marvin UI.
        """
        if self.run_marvin and self._test_run_created:
            self.marvin_ute_client.start_test_run(ref)
            self._test_run_started = True

    def create_test_case_and_start(self, test_case_name, ref_case_id="", adapter_list=None, test_case_templates=None):
        """
        Creates a test case and starts it in Marvin.

        :param str test_case_name: Name of the test case to be created and started.
        :param str ref_case_id: (Optional) Reference case ID for the test case. This is found from Marvin UI.
        :param list adapter_list: (Optional) Adapters for the test case. E.g. ["-cpu-mem"] disables cpu and
                                  memory checks.
        :param list test_case_templates: (Optional) Folder path(s) to the test case templates.
        """
        if self.run_marvin and self._test_run_created:
            self.create_test_case(test_case_name, test_case_templates)
            self.start_test_case(test_case_name, ref=ref_case_id, adapter_list=adapter_list)

    def create_test_case(self, test_case_name, test_case_templates=None):
        """
        Creates a test case in Marvin and imports the analysis templates.

        :param str test_case_name: Name of the test case to be created.
        :param list test_case_templates: (Optional) Folder path(s) to the test case templates.
        """
        if self.run_marvin and self._test_run_created:
            self.marvin_ute_client.create_test_case(test_case_name, test_case_templates)
            self._test_case_created = True

    def start_test_case(self, test_case_name, ref=None, adapter_list=None):
        """
        Starts the test case and updates the verdict in Marvin.

        :param str test_case_name: Name of the test case to be started.
        :param str ref: Reference case ID for the test case. This is found from Marvin UI
        :param list adapter_list: Adapters for the test case. E.g. ["-cpu-mem"] disables cpu and memory checks.
        """
        if self.run_marvin and self._test_case_created:
            self.marvin_ute_client.start_test_case(test_case_name, ref, adapter_list)
            self._test_case_started = True

    def stop_test_case(self, verdict="Passed", test_case_name="", link_to_rp=False, fetch_snapshot=False):
        """
        Stops the test case and updates the verdict in Marvin.

        :param str verdict: Verdict for the test case. Default is "Passed".
        :param str test_case_name: Needed if create_test_cases is initialized as True in prepare_and_start_marvin
        :param bool link_to_rp: If True, url to latest marvin test case is shown in RP. Use either this or in
                                stop_marvin, not both.
        :param bool fetch_snapshot: If True, fetches the snapshot from Marvin before stopping the test case.
        """
        if self.run_marvin and self._test_case_started:
            if fetch_snapshot:
                self.marvin_ute_client.fetch_single_snapshot(test_case=True)
            self.marvin_ute_client.stop_test_case(verdict, test_case_name)
            if link_to_rp:
                self.marvin_ute_client.add_marvin_link_to_rp(test_case_name=test_case_name)

    def stop_test_run(self, verdict="Passed"):
        """
        Stops the test run and updates the verdict in Marvin.

        :param str/bool verdict: Verdict for the test run. Default is "Passed". It can also be a boolean value.
        """
        if self.run_marvin and self._test_run_started:
            self.marvin_ute_client.stop_test_run(verdict)

    def return_final_verdict(self, timeout=20):
        """
        Returns the final verdict of the test run via http-API. If Marvin is not running, it returns True by
        default. Can be used also for waiting analysis instead of dummy 20min wait in stop_marvin (wait_after_run).
        Made by Piotr Lehmann and modified for TAF-library.

        :param str timeout: (Optional) Timeout in minutes for waiting the final verdict. Default is 20 minutes.
        :returns bool: Final verdict of the test run. None if verdict is not available within timeout.
        """
        if self.run_marvin:
            return self.marvin_ute_client.return_final_verdict(timeout)
        return True

    def return_test_case_verdict(self, test_case_name, timeout=20):
        """
        Returns the final verdict of the test case via http-API. If Marvin is not running, it returns True by
        default. NOTE! It can take more than 15min to get the verdict if analysis is not ready yet.

        :param str test_case_name: Name of the test case to get the verdict for.
        :param int timeout: (Optional) Timeout in minutes for waiting the final verdict. Default is 20 minutes.
        :returns bool: Final verdict of the test case.
        """
        if self.run_marvin:
            return self.marvin_ute_client.return_test_case_verdict(test_case_name, timeout)
        return True

    def fetch_snapshot(self):
        """
        Fetches a single snapshot for Marvin.

        """
        if self.run_marvin:
            self.marvin_ute_client.fetch_single_snapshot(periodical=True)

    def add_test_tool_information(self, name, version, type_device, type_hw):
        """
        Adds test tool information for test_env to Marvin test run.

        :param str name: Name of the test environment.
        :param str version: Version of the test environment.
        :param str type_device: Type of the device in the test environment.
        :param str type_hw: Type of the hardware in the test environment.
        """
        test_tool = {"name": name,
                     "version": version,
                     "type": [type_device, type_hw]
                     }
        if "test_tools" not in self.test_env:
            self.test_env["test_tools"] = []
        self.test_env["test_tools"].append(test_tool)
        logging.debug(f"Added test tool information to test env: {test_tool}")
        logging.debug(f"Current test env: {self.test_env}")

    def send_tti_trace_analysis_request_to_ovet(self, file_location, test_case_name=""):
        """
        Sends TTI trace analysis request to Ovet. Use upload_tti_trace_to_analysis_server to upload the trace file
        to the analysis server first. Also TTI trace analysis template has to used. Example file for test run:
        {
            "name": "100861_tti_trace_analyzer",
            "domain": "TTI-Trace",
            "algorithm": "tti-trace-analyzer",
            "trigger": "tti_trace_data_available",
            "tags": [],
            "rule": {
            "lcr_ids": "1",
            "chart_legend": "BTS_100861"
            }
        }
        lcr_ids is important field for analysis to be able to run
        :param str file_location: Location of the TTI trace file. Can be obtained from
                                    upload_tti_trace_to_analysis_server output.
        :param str test_case_name: (Optional) Name of the test case if analysis request is not sent before starting
                                    next test case. Needs create_test_cases to be true on prepare_and_start_marvin.
        """
        if self.run_marvin:
            self.marvin_ute_client.send_results_to_ovet(file_location, test_case_name)

    def upload_tti_trace_to_analysis_server(self, file_location, analysis_name):
        """
        Uploads TTI trace to analysis server. TTI trace file must be zipped pcap file.

        :param str/list file_location: Location of the TTI trace file(s).
        :param str analysis_name: Name of the analysis to be used for OVET analysis request
        :returns str: Name of the analysis name for OVET analysis request
        """
        if self.run_marvin:
            if isinstance(file_location, str):
                file_location = [file_location]
            return self.utils.upload_files_to_analysis_server(file_location, analysis_name)
